"""Loom starter — Basic HTTP GET (Locust)."""

from locust import HttpUser, task, between


class WebsiteUser(HttpUser):
    wait_time = between(1, 3)

    @task(3)
    def index_page(self):
        """Browse landing page."""
        self.client.get("/", name="[GET] /")

    @task(2)
    def view_products(self):
        """Browse catalog."""
        self.client.get("/products", name="[GET] /products")

    @task(1)
    def view_cart(self):
        """Check shopping cart."""
        self.client.get("/cart", name="[GET] /cart")

"""Loom starter — Login + Authenticated API (Locust)."""

from locust import HttpUser, task, between


class AuthUser(HttpUser):
    wait_time = between(1, 3)
    token = ""

    def on_start(self):
        """Log in once per spawned user."""
        with self.client.post(
            "/login",
            json={"username": "demo", "password": "demo"},
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                try:
                    self.token = resp.json().get("token", "")
                except ValueError:
                    self.token = ""
                resp.success()
            else:
                resp.failure(f"login failed: {resp.status_code}")

    @task
    def view_profile(self):
        """Fetch the authenticated profile."""
        headers = {"Authorization": f"Bearer {self.token}"} if self.token else {}
        self.client.get("/api/profile", headers=headers, name="[GET] /api/profile")

"""Loom starter — REST CRUD Workflow (Locust)."""

from locust import HttpUser, task, between


class CrudUser(HttpUser):
    wait_time = between(1, 2)
    item_id = None

    @task(2)
    def create_item(self):
        """Create an item and remember its id."""
        with self.client.post(
            "/api/items", json={"name": "loom-item"}, catch_response=True
        ) as resp:
            if resp.status_code in (200, 201):
                try:
                    self.item_id = resp.json().get("id")
                except ValueError:
                    self.item_id = None
                resp.success()
            else:
                resp.failure(f"create failed: {resp.status_code}")

    @task(3)
    def read_items(self):
        """List all items."""
        self.client.get("/api/items", name="[GET] /api/items")

    @task(1)
    def update_item(self):
        """Update the last created item."""
        if self.item_id is None:
            return
        self.client.put(
            f"/api/items/{self.item_id}",
            json={"name": "loom-item-updated"},
            name="[PUT] /api/items/:id",
        )

    @task(1)
    def delete_item(self):
        """Delete the last created item."""
        if self.item_id is None:
            return
        self.client.delete(
            f"/api/items/{self.item_id}", name="[DELETE] /api/items/:id"
        )
        self.item_id = None

