 */

import http from 'k6/http';
import { check, sleep } from 'k6';

export const options = {
  vus: 10,
  duration: '30s',
  thresholds: {
    http_req_duration: ['p(95)<500'],
  },
};

export default function () {
  const BASE_URL = __ENV.TARGET_HOST || 'http://localhost:8080';

  const res1 = http.get(`${BASE_URL}/`);
  check(res1, {
    'status is 200': (r) => r.status === 200,
  });

  sleep(1);

  const res2 = http.get(`${BASE_URL}/api/data`);
  check(res2, {
    'api status ok': (r) => r.status === 200 || r.status === 404,
  });

  sleep(1);
}

/**
 * Loom starter — Auth Flow (k6).
 */

import http from 'k6/http';
import { check, sleep } from 'k6';

export const options = {
  vus: 10,
  duration: '60s',
  thresholds: {
    http_req_duration: ['p(95)<500'],
  },
};

export function setup() {
  const BASE_URL = __ENV.TARGET_HOST || 'http://localhost:8080';
  const res = http.post(`${BASE_URL}/login`, JSON.stringify({
    username: 'demo',
    password: 'demo',
  }), { headers: { 'Content-Type': 'application/json' } });
  const token = res.status === 200 ? res.json('token') || '' : '';
  return { token };
}

export default function (data) {
  const BASE_URL = __ENV.TARGET_HOST || 'http://localhost:8080';
  const headers = data.token ? { Authorization: `Bearer ${data.token}` } : {};
  const res = http.get(`${BASE_URL}/api/profile`, { headers });
  check(res, {
    'profile status ok': (r) => r.status === 200 || r.status === 401,
  });
  sleep(1);
}

