//! Loom starter — Basic Scenario (Goose).
//!
//! Run with: cargo run --release -- --host http://localhost:8080
//!
//! Requires: goose = "0.18"

use goose::prelude::*;

#[tokio::main]
async fn main() -> Result<(), GooseError> {
    GooseAttack::initialize()?
        .register_scenario(
            scenario!("BrowseUsers")
                .register_transaction(transaction!(browse_index))
                .register_transaction(transaction!(browse_status)),
        )
        .execute()
        .await?;

    Ok(())
}

async fn browse_index(user: &mut GooseUser) -> TransactionResult {
    let _ = user.get("/").await?;
    Ok(())
}

async fn browse_status(user: &mut GooseUser) -> TransactionResult {
    let _ = user.get("/api/v1/status").await?;
    Ok(())
}
